G=load()

def rays(pts,H,W,dirs,exclude=set()):
    o=np.zeros((H,W),bool)
    for p in pts:
        for (dr,dc) in dirs:
            i,j=p[0]+dr,p[1]+dc
            while 0<=i<H and 0<=j<W:
                o[i,j]=True
                i+=dr;j+=dc
    for p in exclude: o[p]=False
    return o

# candidate directions
dirs_all=[]
for a in range(-4,5):
    for b in range(-4,5):
        if abs(a)+abs(b)==1 or abs(a)+abs(b)==2 or (a,b)==(2,3) or (a,b)==(3,2) or (a,b)==(1,2) or (a,b)==(2,1) or (a,b)==(1,3) or (a,b)==(3,1) or (a,b)==(1,1):
            dirs_all.append((a,b))

# For each demo, find direction set whose ray-union matches output exactly
for k in ['Demo pair 6','Demo pair 7']:
    gi=G[k+' input']; go=np.array(G[k+' output'])
    g=np.array(gi); H,W=g.shape
    bg=Counter(g.flatten()).most_common(1)[0][0]
    pts=[(i,j) for i in range(H) for j in range(W) if g[i,j]!=bg]
    sols=[]
    for subset in itertools.chain.from_iterable(itertools.combinations(dirs_all,n) for n in range(1,7)):
        o=rays(set(map(tuple,pts)),H,W,set(subset))
        exp=o.copy()
        # require exact match with output: any difference -> reject
        if o.shape==go.shape and np.array_equal(np.where(o,np.ones_like(go,dtype=bool),np.zeros_like(go)),go.astype(bool)/1):
            pass
        if np.array_equal(o.astype(int),go.astype(int)):
            sols.append(subset)
    print(k,'pts',pts,'exact-sol found:',len(sols)>0, sols[:3])

