def rays_from(pts,H,W,dirs,exclude=None):
    exclude=exclude or set()
    o=np.zeros((H,W),int)
    for p in pts:
        for (dr,dc) in dirs:
            i,j=p[0]+dr,p[1]+dc
            while 0<=i<H and 0<=j<W:
                o[i,j]+=1
                i+=dr;j+=dc
    for p in exclude: o[p]=0
    return o

