    bg=Counter(g.flatten()).most_common(1)[0][0]
    pts=sorted([(i,j) for i in range(H) for j in range(W) if g[i,j]!=bg])
    hits=[]
    for n in range(1,8):
        for subset in itertools.combinations(DIRECS,n):
            o=rays_from(pts,H,W,subset)
            if np.array_equal(o.astype(int),go.astype(int)):
