def comps(g,bg):
    h,w=len(g),len(g[0]); seen=set(); res=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; comp=[]
                while st:
                    x,y=st.pop()
                    if (x,y) in seen: continue
                    seen.add((x,y)); comp.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            xx,yy=x+dx,y+dy
                            if 0<=xx<h and 0<=yy<w and g[xx][yy]==col and (xx,yy) not in seen:
                                st.append((xx,yy))
                res.append((col,len(comp),comp))
    return res
